/**
 * Writes the generated demo asset set to the ignored `.demo/` workspace.
 *
 * The workspace mirrors the Storage bucket + object path, which makes the
 * uploader a straight copy and keeps generated bytes out of git (`.gitignore`
 * ignores `.demo/`). Rebuilding removes the previous tree so a renamed fixture
 * can never leave a stale upload behind.
 */
import { mkdirSync, rmSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

import { renderProjectCover, renderTeamAvatar } from "./art";
import { buildAssetManifest, type DemoAsset } from "./manifest";
import { buildDemoPdf } from "./pdf";

export interface GeneratedAsset {
  readonly asset: DemoAsset;
  readonly buffer: Buffer;
  readonly filePath: string;
}

export function generateAssetBuffer(asset: DemoAsset): Buffer {
  switch (asset.kind) {
    case "cover":
      return renderProjectCover(asset.slug);
    case "avatar":
      return renderTeamAvatar(asset.slug);
    case "publication":
    case "document":
      return buildDemoPdf({
        title: asset.title,
        subtitle: asset.subtitle,
        lines: asset.lines
      });
  }
}

/**
 * Generates and writes the whole manifest.
 *
 * `root` is explicit so tests can use a temporary directory; the entrypoint
 * passes `<repo>/.demo/assets`, which is git-ignored.
 */
export function writeDemoAssets(
  root: string,
  manifest: readonly DemoAsset[] = buildAssetManifest()
): GeneratedAsset[] {
  rmSync(root, { recursive: true, force: true });

  return manifest.map(asset => {
    const buffer = generateAssetBuffer(asset);
    const filePath = join(root, asset.bucket, asset.path);
    mkdirSync(dirname(filePath), { recursive: true });
    writeFileSync(filePath, buffer);
    return { asset, buffer, filePath };
  });
}
